	if src != nil && !src.IsUnspecified() {
		srcFamily := addressFamily(src)
		if srcFamily != dstFamily {
			return nil, nil, nil, fmt.Errorf("source %q and destination %q use different address families", src.String(), dst.String())
		}
	}

