	if len(input) > 0 {
		ifaces, err := net.Interfaces()
		if err != nil {
			return nil, nil, nil, fmt.Errorf("list interfaces: %w", err)
		}
		for i := range ifaces {
			iface := ifaces[i]
			if bytes.Equal(iface.HardwareAddr, input) {
				oif = iface.Index
				break
			}
		}
		if oif == 0 {
			return nil, nil, nil, fmt.Errorf("no interface with address %s found", input.String())
		}
