398	
399	func TestPathPasteReachesTheFieldWhileEditing(t *testing.T) {
400		pm, _ := newPM(t)
401		pm, _ = pmFeed(t, pm, testutil.Paste("example.com"))
402		if got := pm.input.Value(); got != "example.com" {
403			t.Errorf("field = %q after a paste, want example.com", got)
404		}
405		if pm.running() {
406			t.Error("a paste launched a trace")
407		}
408	}
409	
410	func TestPathDoneEnterRelaunchesAndEscEdits(t *testing.T) {
411		// update mutates and returns the same model, so each branch gets its own.
412		newDone := func() *PathModel {
413			pm, _ := newPM(t)
414			pm, _ = launched(t, pm, "1.1.1.1:443")
415			pm, _ = pmFeed(t, pm, pathDoneMsg{gen: pm.gen, result: nettrace.Result{
416				Outcome: nettrace.OutcomeReached, Hops: []nettrace.Hop{hopOf(1, nettrace.HopTarget)},
417			}})
418			return pm
419		}
420		pm := newDone()
421		g := pm.gen
422	
423		if v, _ := headerValue(pm, "Target"); !strings.Contains(v, "1.1.1.1:443") {
424			t.Errorf("Target header = %q, want the host:port", v)
425		}
426		if !testutil.ShortcutEnabled(pm.shortcuts(), "enter") || !testutil.HasShortcut(pm.shortcuts(), "esc") {
427			t.Errorf("done shortcuts = %v, want enter and esc", testutil.ShortcutKeys(pm.shortcuts()))
428		}
429	
430		again, cmd := pmFeed(t, pm, testutil.Key("enter"))
431		if cmd == nil || !again.running() || again.gen != g+1 || again.target != (pathTarget{Host: "1.1.1.1", Port: 443}) {
432			t.Errorf("relaunch: cmd=%v running=%v gen=%d target=%v", cmd != nil, again.running(), again.gen, again.target)
433		}
434	
435		edit, _ := pmFeed(t, newDone(), testutil.Key("esc"))
436		if !edit.InEditMode() || edit.input.Value() != "1.1.1.1:443" {
437			t.Errorf("esc from done: edit=%v value=%q, want editing with the value kept", edit.InEditMode(), edit.input.Value())
438		}
439		if len(edit.table.Items()) != 1 {
440			t.Errorf("rows after esc from done = %d, want hops kept until the next launch", len(edit.table.Items()))
441		}
442	}
443	
444	// Rule 130: the key set is the same in every state of one screen, except the
445	// running mode that replaces the list.
446	func TestPathShortcutsPerState(t *testing.T) {
447		pm, _ := newPM(t)
448		if !testutil.HasShortcut(pm.shortcuts(), "tab") {
449			t.Error("editing lacks tab")
