451		run, _ := launched(t, pm, "1.1.1.1")
452		if !testutil.ShortcutEnabled(run.shortcuts(), "esc") {
453			t.Errorf("running shortcuts = %v, want esc", testutil.ShortcutKeys(run.shortcuts()))
454		}
455		for _, s := range run.shortcuts() {
456			if s.Key == "esc" && s.Description != "Cancel the trace" {
457				t.Errorf("running esc = %q, want Cancel the trace", s.Description)
458			}
459		}
460	}
461	
462	// Criterion 6, Rules 128/139: the body is the table in every state and the
463	// footer slot has a fixed height.
464	func TestPathBodyIsTheTableAndFooterHeightIsFixed(t *testing.T) {
465		idle, _ := newPM(t)
466		run, _ := launched(t, mustPM(t), "1.1.1.1")
467		done, _ := pmFeed(t, run, pathDoneMsg{gen: run.gen, result: nettrace.Result{Outcome: nettrace.OutcomeReached}})
468		failed, _ := pmFeed(t, mustPM(t), testutil.Key("enter"))
469	
470		wantBar := strings.Count(idle.barView(100), "\n")
471		for name, pm := range map[string]*PathModel{"idle": idle, "running": run, "done": done, "refused": failed} {
472			if got, want := pm.view(), pm.table.View(); got != want {
473				t.Errorf("%s: view() is not the table view", name)
474			}
475			if got := strings.Count(pm.barView(100), "\n"); got != wantBar {
476				t.Errorf("%s: bar has %d line breaks, want %d (constant footer height)", name, got, wantBar)
477			}
478			if got := strings.Count(pmFooter(pm, 100), "\n"); got != 0 {
479				t.Errorf("%s: message line has %d line breaks, want a single line", name, got)
480			}
481		}
