486		pm, _ := newPM(t)
487		return pm
488	}
489	
490	// Rule 116.
491	func TestPathTableFillsTheViewport(t *testing.T) {
492		for _, w := range []int{120, 60} {
493			pm, _ := newPM(t)
494			pm.resize(w, 30)
