501	// A done message always carries a usable Result: a cancel leaves one, and the
502	// header never reads a nil result.
503	func TestPathHeaderNeverReadsANilResult(t *testing.T) {
504		pm, _ := newPM(t)
505		if _, ok := headerValue(pm, "Path"); ok {
